'use client'

import { useEffect, useState } from 'react'

interface SuspenseTransitionProps {
  children: React.ReactNode
  fallback: React.ReactNode
}

export function SuspenseTransition({ children, fallback }: SuspenseTransitionProps) {
  const [showContent, setShowContent] = useState(false)
  const [showFallback, setShowFallback] = useState(true)

  useEffect(() => {
    if (showContent) {
      setShowFallback(false)
    }
  }, [showContent])

  return (
    <div className="suspense-transition">
      {showFallback && (
        <div className={`fallback-wrapper ${showContent ? 'fade-out' : ''}`}>
          {fallback}
        </div>
      )}
      <div className={`content-wrapper ${showContent ? 'visible' : ''}`}>
        {children}
      </div>
    </div>
  )
}

function ClientFallback({ children }: { children: React.ReactNode }) {
  return <>{children}</>
}

