import { useState, useEffect, ReactNode } from 'react'

interface SuspenseTransitionProps {
  fallback: ReactNode
  children: ReactNode
}

export function SuspenseTransition({ fallback, children }: SuspenseTransitionProps) {
  const [isResolved, setIsResolved] = useState(false)

  useEffect(() => {
    setIsResolved(true)
  }, [])

  return (
    <div className="suspense-transition-wrapper">
      <div className={`suspense-fallback ${isResolved ? 'resolving' : ''}`}>
        {fallback}
      </div>
      <div className={`suspense-content ${isResolved ? 'resolved' : ''}`}>
        {children}
      </div>
    </div>
  )
}

