export function useSuspenseTransition() {
  const [showContent, setShowContent] = useState(false)
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    setMounted(true)
  }, [])

  const onContentVisible = () => {
    setShowContent(true)
  }

  return { showContent, mounted, onContentVisible }
}

