export function ProductDetailContent({ children, fallback }: ProductDetailContentProps) {
  const [showContent, setShowContent] = useState(false)

  useEffect(() => {
    const timer = setTimeout(() => setShowContent(true), 150)
    return () => clearTimeout(timer)
  }, [])

  return (
    <div className="product-detail-content">
      <div className={`detail-skeleton ${showContent ? 'skeleton-exit' : ''}`}>
        {fallback}
      </div>
      <div className={`detail-actual ${showContent ? 'content-enter' : ''}`}>
        {children}
      </div>
    </div>
  )
}

